INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json) VALUES ('c737e6b93220471d68d2286a35c6868a', '1758872409.023532', 'D05V2N6PZNU', 'message', 'EMPLOYEE_0009_SLACK_ID', 'Hey Marcus, could you try a quick halloween pass on one of the current cuts when you have a minute? Just to see how it reads before we plan anything', NULL, '1758872409.023532', 1, 1, '1759166437.080255', false, NULL, '[]', '[]', '[]', '2025-09-26T07:40:09.023532Z', '{}');
