INSERT INTO gsheets.sheets_sheets (spreadsheet_id, sheet_id, title, "index", row_count, column_count, grid_json) VALUES ('f_02b1968f5e882366fbb883', 0, 'Read me', 0, 1000, 1, '[["One row per creative serving on our four Unity retention campaigns today (iOS UK phone, iOS UK tablet, Android US phone, Android US tablet) plus the store listing sets. Paused or retired creatives move to Archive. Each Unity row links its ART ticket; campaigns, capture and master notes are in the ticket comments. Store sets have no ART ticket. Halloween push: see the Halloween push card on the ZM roadmap."]]');
